import{_ as s,C as c,o as l,c as n,j as d,a as e,E as o,a5 as r}from"./chunks/framework.BYIUCCsM.js";const T=JSON.parse('{"title":"轻提示","description":"","frontmatter":{},"headers":[],"relativePath":"components/toast.md","filePath":"components/toast.md","lastUpdated":1787679442000}'),h={name:"components/toast.md"},u={id:"轻提示",tabindex:"-1"};function b(p,t,g,x,m,f){const i=c("Badge"),a=c("XhDemo");return l(),n("div",null,[d("h1",u,[t[0]||(t[0]=e("轻提示 ",-1)),o(i,{type:"info",text:"toast"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#轻提示","aria-label":'Permalink to "轻提示 <Badge type="info" text="toast" />"'},"​",-1))]),t[3]||(t[3]=r('<p>一条会自己消失的短反馈：一枚状态字形加一句话，横排一行、贴着文字收缩。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>一次操作的结果：&quot;已保存&quot;、&quot;已复制&quot;、&quot;发送失败&quot;。</li><li>反馈重要但不需要打断用户。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>用户必须知道并处理：用<a href="./alert">警告提示</a>让它常驻，或用<a href="./dialog">对话框</a>阻断。</li><li>内容较长、分标题与正文两层，或不是用户点出来的：用<a href="./notification">通知</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>duration</code> 决定停留时长，指针悬停或页面失焦时计时暂停。</li><li>可以带一个操作按钮（撤销、查看详情）。</li><li><code>type</code> 决定语气：淡底、描边与状态字形一起换族，正文留中性。</li><li>组件档 <code>closable</code> 缺省为真，叉写不写由作者定；全局服务的默认模板反过来—— 到点自己走的不出叉，走不掉的（<code>loading</code>、<code>duration</code> 给 0）才出。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>一条一句话：title 部件留空时由属性上的文案填入；duration 给 0 即不自动消失</p>',10)),o(a,{src:"toast/01-basic"}),t[4]||(t[4]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[5]||(t[5]=d("p",null,"type 落成 data-type，淡底、描边与字形一起换族，正文留中性；error 走 alert + assertive，loading 表示事情还没完、不自动消失",-1)),o(a,{src:"toast/02-type"}),t[6]||(t[6]=d("h3",{id:"计时与暂停",tabindex:"-1"},[e("计时与暂停 "),d("a",{class:"header-anchor",href:"#计时与暂停","aria-label":'Permalink to "计时与暂停"'},"​")],-1)),t[7]||(t[7]=d("p",null,"duration 走完自动退场；指针停在条子上或焦点进到条子里都会把计时按住，离开才接着走剩下那一段",-1)),o(a,{src:"toast/03-pause"}),t[8]||(t[8]=d("h3",{id:"操作按钮",tabindex:"-1"},[e("操作按钮 "),d("a",{class:"header-anchor",href:"#操作按钮","aria-label":'Permalink to "操作按钮"'},"​")],-1)),t[9]||(t[9]=d("p",null,"action-trigger 按下时先发 action 事件，再让这条进入退场；closable 决定还要不要那颗叉",-1)),o(a,{src:"toast/04-action"}),t[10]||(t[10]=d("h3",{id:"自定义排版",tabindex:"-1"},[e("自定义排版 "),d("a",{class:"header-anchor",href:"#自定义排版","aria-label":'Permalink to "自定义排版"'},"​")],-1)),t[11]||(t[11]=d("p",null,"条子本身就是一行 flex，摆什么、摆在哪一侧都归作者；组件只管盒子、计时与退场",-1)),o(a,{src:"toast/05-icon"}),t[12]||(t[12]=d("h3",{id:"全局服务",tabindex:"-1"},[e("全局服务 "),d("a",{class:"header-anchor",href:"#全局服务","aria-label":'Permalink to "全局服务"'},"​")],-1)),t[13]||(t[13]=d("p",null,"轻提示没有容器组件，那一摞由 createToastService 渲染；模块作用域随处可调（请求拦截器、store）",-1)),o(a,{src:"toast/06-service"}),t[14]||(t[14]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-toast&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhToastActionTrigger</code> <code>XhToastCloseTrigger</code> <code>XhToastRoot</code> <code>XhToastTitle</code></td></tr><tr><td>组合式函数</td><td><code>useToast</code></td></tr><tr><td>状态机</td><td><code>toastMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/toast.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;toast&quot;</code>：<strong><code>root</code></strong> · <code>title</code> · <code>action-trigger</code> · <code>close-trigger</code> · <code>group</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td></td><td>队列身份。服务档用它做 create/update/dismiss 的寻址键。</td></tr><tr><td><code>title</code></td><td><code>string</code></td><td></td><td>标题文本；作者没在 title 部件里写内容时由适配器填入。</td></tr><tr><td><code>description</code></td><td><code>string</code></td><td></td><td>补充说明。轻提示自己不出这一层——两层文本是 notification 的活； 这条 prop 留着是因为 notification 的单条卡片复用同一台机器。</td></tr><tr><td><code>type</code></td><td><code>ToastType</code></td><td></td><td>语气，默认 info。error 走 alert + assertive，loading 不自动消失。</td></tr><tr><td><code>duration</code></td><td><code>number</code></td><td></td><td>停留毫秒，默认 5000。&lt;=0 或非有限数即不自动消失。</td></tr><tr><td><code>removeDelay</code></td><td><code>number</code></td><td></td><td>退场窗口毫秒，默认 200：进入 dismissing 后停留这么久再转 unmounted，留给退场动画。</td></tr><tr><td><code>closable</code></td><td><code>boolean</code></td><td></td><td>是否显示可用的关闭按钮，默认 true。</td></tr><tr><td><code>pauseOnPageIdle</code></td><td><code>boolean</code></td><td></td><td>页面切到后台时暂停计时，默认 false。由服务档统一下发。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ToastTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onStatusChange</code></td><td><code>(details: ToastStatusChangeDetails) =&gt; void</code></td><td></td><td>生命周期落位时通知：dismissing 与 unmounted 各一次。宿主据此把条目移出队列。</td></tr><tr><td><code>onAction</code></td><td><code>(details: ToastActionDetails) =&gt; void</code></td><td></td><td>操作按钮被按下。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>status-change</code></td><td><code>ToastStatusChangeDetails</code></td><td>生命周期落位；detail 为 <code>{ id: string, status: &#39;dismissing&#39;|&#39;unmounted&#39; }</code></td></tr><tr><td><code>action</code></td><td><code>ToastActionDetails</code></td><td>操作按钮被按下；detail 为 <code>{ id: string }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhToastRoot</code></td><td><code>default</code></td><td><code>ToastRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>toStatus(state.get())</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>visible</code> · <code>visible.running</code> · <code>visible.paused</code> · <code>dismissing</code> · <code>unmounted</code></p><p><strong>事件</strong>：<code>TOAST.DISMISS</code> · <code>TOAST.ACTION</code> · <code>TOAST.PAUSE</code> · <code>TOAST.RESUME</code> · <code>TOAST.RESET</code> · <code>after.duration</code> · <code>after.removeDelay</code></p><p><strong>判据</strong>：<code>isLastPauseSource</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useToast</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td></td></tr><tr><td><code>status</code></td><td><code>ToastStatus</code></td><td></td></tr><tr><td><code>type</code></td><td><code>ToastType</code></td><td></td></tr><tr><td><code>title</code></td><td><code>string | undefined</code></td><td></td></tr><tr><td><code>paused</code></td><td><code>boolean</code></td><td>计时被按住中。倒计时的可见反馈由使用者自己渲染，这个标记是留给他的钩子——自带皮肤不画。</td></tr><tr><td><code>closable</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>remaining</code></td><td><code>number</code></td><td>剩余毫秒；不自动消失时为 Infinity。</td></tr><tr><td><code>dismiss</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>pause</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>resume</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getActionTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/alert/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus 在 close-trigger 上且 closable</td><td>立即进入 dismissing，走完 removeDelay 后转 unmounted</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus 在 action-trigger 上</td><td>触发 onAction 并进入 dismissing</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-live</code></td><td>&#39;assertive&#39; | &#39;polite&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;alert&#39; | &#39;status&#39;</td></tr><tr><td><code>close-trigger</code></td><td><code>aria-label</code></td><td>props.translations.close</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/toast.css</code> 按部件选择：<code>[data-scope=&quot;toast&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-paused</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>toStatus(state.get())</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>toneOf(type)</td></tr><tr><td><code>root</code></td><td><code>data-type</code></td><td>props.type</td></tr><tr><td><code>close-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-toast-action-bg</code> · <code>--xh-toast-action-bg-active</code> · <code>--xh-toast-action-bg-hover</code> · <code>--xh-toast-action-border</code> · <code>--xh-toast-action-fg</code> · <code>--xh-toast-action-font-weight</code> · <code>--xh-toast-action-h</code> · <code>--xh-toast-action-px</code> · <code>--xh-toast-action-radius</code> · <code>--xh-toast-bg</code> · <code>--xh-toast-border</code> · <code>--xh-toast-close-bg-active</code> · <code>--xh-toast-close-bg-hover</code> · <code>--xh-toast-close-fg</code> · <code>--xh-toast-close-fg-hover</code> · <code>--xh-toast-close-radius</code> · <code>--xh-toast-close-size</code> · <code>--xh-toast-fg</code> · <code>--xh-toast-font-size</code> · <code>--xh-toast-gap</code> · <code>--xh-toast-icon-size</code> · <code>--xh-toast-inset</code> · <code>--xh-toast-layer</code> · <code>--xh-toast-leading</code> · <code>--xh-toast-px</code> · <code>--xh-toast-py</code> · <code>--xh-toast-radius</code> · <code>--xh-toast-shadow</code> · <code>--xh-toast-title-fg</code> · <code>--xh-toast-title-font-size</code> · <code>--xh-toast-title-font-weight</code> · <code>--xh-toast-title-leading</code> · <code>--xh-toast-w</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-toast-in</code> · <code>xh-toast-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>没有容器组件：那一摞由全局服务渲染，业务代码 <code>toast.success(&#39;已保存&#39;)</code> 一行调用即可。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>破坏性操作配&quot;撤销&quot;按钮，比事前确认对话框体验好得多。</li><li>错误类的提示停留久一点，或干脆不自动消失。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把错误详情放进轻提示：用户还没读完就没了。</li><li>同一个动作连发好几条。</li></ul>',48))])}const P=s(h,[["render",b]]);export{T as __pageData,P as default};
